#include <string.h>

int main(void) {
    char placa[16];
    scanf("%15s", placa);

    int n = (int)strlen(placa);
    int valido = 1;

    if (n == 8) {
        for (int i = 0; i < 3; i++)
            if (placa[i] < 'A' || placa[i] > 'Z') valido = 0;

        if (placa[3] != '-') valido = 0;

        for (int i = 4; i < 8; i++)
            if (placa[i] < '0' || placa[i] > '9') valido = 0;

        puts(valido ? "1" : "0");
    } else if (n == 7) {
        for (int i = 0; i < 3; i++)
            if (placa[i] < 'A' || placa[i] > 'Z') valido = 0;

        if (placa[3] < '0' || placa[3] > '9') valido = 0;
        if (placa[4] < 'A' || placa[4] > 'Z') valido = 0;

        for (int i = 5; i < 7; i++)
            if (placa[i] < '0' || placa[i] > '9') valido = 0;

        puts(valido ? "2" : "0");
    } else {
        puts("0");
    }

    return 0;
}
